{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "This systematic review and meta-analysis aim to identify contributors to energy use in hotel buildings, provide a descriptive picture of the research stream, and synthesize the theoretical foundation in each variable, and determine the magnitude of the mean effect size on hotels' energy use. The research fulfils the lack of systematic reviews and meta-analyses considering energy use and its contributors in hotel buildings and the lack of theoretical frameworks on these relationships.",
      "reason": "The current state of knowledge is described as having a lack of systematic reviews/meta-analyses and lack of theoretical frameworks, but the evidence provided does not clearly describe “important uncertainties” beyond these stated gaps."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "With this, a pressing need by the decision-makers of the hotel industry to reduce their energy consumption is becoming relevant [20]. ... This systematic review and meta-analysis aim to identify contributors to energy use in hotel buildings, provide a descriptive picture of the research stream, and synthesize the theoretical foundation in each variable, and determine the magnitude of the mean effect size on hotels' energy use.",
      "reason": "The manuscript explains the need for the review in relation to a pressing need to reduce hotel energy consumption and states what the review will synthesize/identify."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "A search for previous reviews was done, but neither a systematic review nor a meta-analysis involving energy use and its contributors in hotels was found until the day before the protocol registration, October 26, 2023.",
      "reason": "The conditional requirement is met by explaining that prior systematic reviews/meta-analyses on the specific topic were not found, supporting the rationale for conducting the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No intervention effects or mechanism-of-action of an intervention are described in the retrieved evidence, so this criterion does not apply to the systematic review rationale presented."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe a complex intervention or delivery context requiring a logic model; the review focuses on contributors to energy use in hotel buildings."
    }
  ],
  "confidence": 62
}

